package io.github.diodeme.ji.provider.openai;

import io.github.diodeme.ji.ai.CredentialReference;
import io.github.diodeme.ji.ai.CredentialResolver;
import io.github.diodeme.ji.ai.ModelCatalog;
import io.github.diodeme.ji.ai.ModelProvider;
import io.github.diodeme.ji.ai.ModelRequest;
import io.github.diodeme.ji.ai.ModelResponse;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.ProviderModel;
import io.github.diodeme.ji.ai.ProviderProfile;
import io.github.diodeme.ji.ai.ProviderProtocolFamily;
import io.github.diodeme.ji.ai.SensitiveHeader;
import io.github.diodeme.ji.provider.http.HttpModelProvider;
import io.github.diodeme.ji.provider.http.ProviderEndpoints;
import java.net.URI;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.Flow;

/** OpenAI-compatible Chat Completions adapter. */
public final class OpenAiProvider implements ModelProvider {
    private final HttpModelProvider delegate;

    private OpenAiProvider(ProviderProfile profile, CredentialResolver credentials) {
        delegate = new HttpModelProvider(profile, credentials, new OpenAiWireAdapter());
    }

    public static OpenAiProvider create(ProviderProfile profile, CredentialResolver credentials) {
        if (profile.family() != ProviderProtocolFamily.OPENAI_COMPATIBLE) {
            throw new IllegalArgumentException("profile family must be openai-compatible");
        }
        return new OpenAiProvider(profile, credentials);
    }

    public static Builder builder() {
        return new Builder();
    }

    public URI endpoint() {
        return ProviderEndpoints.v1(delegate.profile().baseUrl(), "chat/completions");
    }

    @Override public Flow.Publisher<ModelStreamEvent> stream(ModelRequest request) { return delegate.stream(request); }
    @Override public CompletionStage<ModelResponse> complete(ModelRequest request) { return delegate.complete(request); }
    @Override public CompletionStage<Void> closeAsync() { return delegate.closeAsync(); }

    public static URI normalizeEndpoint(String baseUrl) {
        return ProviderEndpoints.v1(URI.create(baseUrl), "chat/completions");
    }

    public static final class Builder {
        private String baseUrl;
        private CredentialReference credential = CredentialReference.none();
        private CredentialResolver resolver = CredentialResolver.none();
        private final List<SensitiveHeader> headers = new ArrayList<>();

        public Builder baseUrl(String value) { baseUrl = value; return this; }
        public Builder credential(CredentialReference reference, CredentialResolver value) {
            credential = java.util.Objects.requireNonNull(reference, "reference");
            resolver = java.util.Objects.requireNonNull(value, "value");
            return this;
        }
        public Builder header(SensitiveHeader value) {
            headers.add(java.util.Objects.requireNonNull(value, "value"));
            return this;
        }

        public OpenAiProvider build() {
            String model = "configured-model";
            ProviderProfile profile = new ProviderProfile("openai-default", ProviderProtocolFamily.OPENAI_COMPATIBLE,
                    URI.create(baseUrl), credential, headers,
                    ModelCatalog.fixed(List.of(new ProviderModel(model, model,
                            Set.of(ProviderModel.Capability.TEXT, ProviderModel.Capability.STREAMING,
                                    ProviderModel.Capability.TOOL_CALL, ProviderModel.Capability.USAGE), Map.of()))),
                    model, Map.of(), 0);
            return new OpenAiProvider(profile, resolver);
        }
    }
}

